-- =========================================================
-- MIGRASI: GANTI INSTRUMEN SUPERVISI -> Instrumen SMK (Pembelajaran Mendalam)
--   Sumber: 1-Instrumen-Pra-Supervisi-SMK, 2-Instrumen-Supervisi-Pembelajaran-SMK,
--           3-Instrumen-Tindak-Lanjut-Supervisi-SMK
--   - Form Pra-Supervisi  : Dokumen 1 (A.1 identitas, A.2 telaah perangkat, A.3 wawancara, kesimpulan)
--   - Form Supervisi      : Dokumen 2 (24 indikator skala 1-4 + bukti) + Dokumen 3 (tindak lanjut C.1-C.4)
--   - Form Supervisi menjadi INDUK paket dan memuat form Pra-Supervisi (boleh diisi kapan saja).
--   - Jadwal yang masih 'terjadwal' dipindah ke form Supervisi baru.
--   - Form lama TIDAK dihapus (diberi awalan "[Lama]") supaya hasil supervisi yang sudah selesai tetap terbaca.
-- Jalankan di Supabase SQL Editor SETELAH migrasi_supervisi_paket.sql. Aman diulang.
-- =========================================================

insert into public.supervisi_form (jenis, judul, pertanyaan)
select 'pra', 'Instrumen Pra-Supervisi Akademik SMK (Pembelajaran Mendalam)', $j$[{"tipe": "bagian", "teks": "Petunjuk", "keterangan": "Isi sebelum observasi pembelajaran. Pada telaah perangkat, pilih Ada / Sesuai / Perlu perbaikan lalu tulis catatan.\n\nLandasan regulasi: Permendikdasmen No. 13/2025 (pendekatan pembelajaran mendalam), No. 10/2025 (SKL), No. 12/2025 (Standar Isi); Kepka BSKAP No. 046/H/KR/2025 (Capaian Pembelajaran); Permendikbudristek No. 16/2022 (Standar Proses) dan No. 21/2022 (Standar Penilaian); Permendiknas No. 12/2007 (Standar Pengawas); Permendikbud No. 6/2018. Verifikasi ulang regulasi terbaru di jdih.kemdikbud.go.id sebelum dipakai secara resmi.", "id": "q1"}, {"tipe": "bagian", "teks": "A.1 Identitas dan Kesepakatan", "id": "q2"}, {"tipe": "info", "teks": "NIP guru", "id": "q3"}, {"tipe": "info", "teks": "Kompetensi keahlian", "id": "q4"}, {"tipe": "info", "teks": "Fase", "id": "q5"}, {"tipe": "info", "teks": "Semester / Tahun ajaran", "id": "q6"}, {"tipe": "info", "teks": "Kelompok mapel (Umum / Dasar Program / Kejuruan / Projek IPAS / PKL)", "id": "q7"}, {"tipe": "info", "teks": "Topik dan Tujuan Pembelajaran yang diamati", "id": "q8"}, {"tipe": "info", "teks": "Hari, tanggal, jam ke-, ruang/bengkel/lab", "id": "q9"}, {"tipe": "info", "teks": "Fokus supervisi (pilih minimal satu: Praktik pedagogis / Kemitraan / Lingkungan belajar / Pemanfaatan digital / Asesmen / Pembelajaran kejuruan TEFA-DUDI)", "id": "q10"}, {"tipe": "bagian", "teks": "A.2 Telaah Perangkat Pembelajaran", "keterangan": "Pilih Ada, Sesuai, atau Perlu perbaikan, lalu isi catatan.", "id": "q11"}, {"tipe": "pilihan", "teks": "Capaian Pembelajaran (CP) mengacu pada Kepka BSKAP 046/2025 sesuai fase dan mata pelajaran/elemen kejuruan", "opsi": ["Ada", "Sesuai", "Perlu perbaikan"], "komentar": "Catatan", "id": "q12"}, {"tipe": "pilihan", "teks": "Tujuan Pembelajaran (TP) dan Alur TP: jelas, terukur, berurutan, memuat kompetensi dan lingkup materi", "opsi": ["Ada", "Sesuai", "Perlu perbaikan"], "komentar": "Catatan", "id": "q13"}, {"tipe": "pilihan", "teks": "Rencana pembelajaran/modul ajar memuat identifikasi murid, dimensi profil lulusan, serta desain pembelajaran (TP, kerangka, topik, kemitraan, lingkungan, digital)", "opsi": ["Ada", "Sesuai", "Perlu perbaikan"], "komentar": "Catatan", "id": "q14"}, {"tipe": "pilihan", "teks": "Kerangka pembelajaran: praktik pedagogis (PjBL, TEFA, inkuiri, problem-based, dll.), kemitraan, lingkungan belajar, dan pemanfaatan digital direncanakan", "opsi": ["Ada", "Sesuai", "Perlu perbaikan"], "komentar": "Catatan", "id": "q15"}, {"tipe": "pilihan", "teks": "Prinsip berkesadaran, bermakna, dan menggembirakan (mindful, meaningful, joyful) tercermin dalam rancangan kegiatan", "opsi": ["Ada", "Sesuai", "Perlu perbaikan"], "komentar": "Catatan", "id": "q16"}, {"tipe": "pilihan", "teks": "Pengalaman belajar memahami, mengaplikasi, dan merefleksi dirancang berjenjang", "opsi": ["Ada", "Sesuai", "Perlu perbaikan"], "komentar": "Catatan", "id": "q17"}, {"tipe": "pilihan", "teks": "Kontekstualisasi dengan dunia kerja (DUDI), standar kompetensi kerja/SKKNI, K3LH, atau produk/jasa TEFA", "opsi": ["Ada", "Sesuai", "Perlu perbaikan"], "komentar": "Catatan", "id": "q18"}, {"tipe": "pilihan", "teks": "Dimensi Profil Lulusan (keimanan dan ketakwaan, kewargaan, penalaran kritis, kreativitas, kolaborasi, kemandirian, kesehatan, komunikasi) dipilih relevan dengan TP", "opsi": ["Ada", "Sesuai", "Perlu perbaikan"], "komentar": "Catatan", "id": "q19"}, {"tipe": "pilihan", "teks": "Asesmen diagnostik (kognitif/non-kognitif) dan tindak lanjutnya", "opsi": ["Ada", "Sesuai", "Perlu perbaikan"], "komentar": "Catatan", "id": "q20"}, {"tipe": "pilihan", "teks": "Asesmen formatif dan sumatif selaras TP, dilengkapi instrumen/rubrik (unjuk kerja, portofolio, produk)", "opsi": ["Ada", "Sesuai", "Perlu perbaikan"], "komentar": "Catatan", "id": "q21"}, {"tipe": "pilihan", "teks": "Diferensiasi dan inklusivitas (konten, proses, produk; kebutuhan khusus) direncanakan", "opsi": ["Ada", "Sesuai", "Perlu perbaikan"], "komentar": "Catatan", "id": "q22"}, {"tipe": "pilihan", "teks": "Media, alat, bahan, bengkel/lab, dan keselamatan kerja tersedia dan layak", "opsi": ["Ada", "Sesuai", "Perlu perbaikan"], "komentar": "Catatan", "id": "q23"}, {"tipe": "pilihan", "teks": "Pemanfaatan teknologi (termasuk AI secara etis) dan kebijakan integritas akademik murid", "opsi": ["Ada", "Sesuai", "Perlu perbaikan"], "komentar": "Catatan", "id": "q24"}, {"tipe": "bagian", "teks": "A.3 Wawancara Pra-Observasi", "keterangan": "Isi dengan jawaban guru.", "id": "q25"}, {"tipe": "teks", "teks": "Apa tujuan pembelajaran hari ini dan bagaimana murid akan memahaminya secara mendalam, bukan sekadar hafal?", "id": "q26"}, {"tipe": "teks", "teks": "Bagaimana kondisi awal murid (hasil diagnostik, gaya belajar, kesiapan) memengaruhi rancangan Anda?", "id": "q27"}, {"tipe": "teks", "teks": "Pengalaman belajar apa yang membuat topik ini bermakna dan terkait dunia kerja?", "id": "q28"}, {"tipe": "teks", "teks": "Bagaimana Anda mengecek pemahaman dan memberi umpan balik selama pembelajaran?", "id": "q29"}, {"tipe": "teks", "teks": "Tantangan apa yang Anda antisipasi, dan dukungan apa yang Anda butuhkan dari supervisor?", "id": "q30"}, {"tipe": "bagian", "teks": "Kesimpulan", "id": "q31"}, {"tipe": "teks", "teks": "Kesimpulan pra-supervisi / kesepakatan:", "id": "q32"}]$j$::jsonb
where not exists (select 1 from public.supervisi_form where judul = 'Instrumen Pra-Supervisi Akademik SMK (Pembelajaran Mendalam)');

insert into public.supervisi_form (jenis, judul, pertanyaan)
select 'supervisi', 'Instrumen Supervisi Pembelajaran dan Tindak Lanjut SMK (Pembelajaran Mendalam)', $j$[{"tipe": "bagian", "teks": "Skala Penilaian", "keterangan": "4 = Sangat Baik – konsisten, ada bukti, berdampak pada murid\n3 = Baik – sebagian besar terpenuhi\n2 = Cukup – muncul sebagian / tidak konsisten\n1 = Kurang – belum tampak\n\nBeri skor 1–4 dan tulis bukti pengamatan. Indikator bertanda (K) khusus pembelajaran kejuruan.\nNilai = (skor diperoleh ÷ skor maksimal) × 100; skor maksimal 96 (24 indikator), atau 80 (20 indikator) bila mapel non-kejuruan. Kategori: 86–100 Sangat Baik · 71–85 Baik · 56–70 Cukup · ≤55 Perlu Pembinaan.\n\nPilih dulu Jenis mata pelajaran. Bila Non-kejuruan, indikator bertanda (K) disembunyikan dan tidak dihitung.", "id": "q1"}, {"tipe": "pilihan", "teks": "Jenis mata pelajaran yang disupervisi", "opsi": ["Kejuruan (produktif / dasar program)", "Non-kejuruan (umum)"], "id": "q2"}, {"tipe": "bagian", "teks": "B. Instrumen Supervisi Pembelajaran", "id": "q3"}, {"tipe": "bagian", "teks": "I. Kegiatan Awal (Berkesadaran)", "id": "q4"}, {"tipe": "skala", "teks": "Menciptakan suasana siap belajar (salam, doa/refleksi, K3 untuk praktik); kehadiran dan kondisi murid dicek", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q5"}, {"tipe": "skala", "teks": "Apersepsi dan pemantik yang mengaitkan pengalaman murid / situasi dunia kerja", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q6"}, {"tipe": "skala", "teks": "Menyampaikan TP dan kriteria keberhasilan secara jelas; murid memahami arah belajarnya", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q7"}, {"tipe": "bagian", "teks": "II. Kegiatan Inti – Praktik Pedagogis", "id": "q8"}, {"tipe": "skala", "teks": "Penguasaan materi akurat, mutakhir, dan selaras CP/TP", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q9"}, {"tipe": "skala", "teks": "Model/metode sesuai karakter materi (PjBL, TEFA, problem-based, demonstrasi) dan sintaksnya runtut", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q10"}, {"tipe": "skala", "teks": "Pengalaman MEMAHAMI: murid membangun konsep dan menghubungkan antar-konsep", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q11"}, {"tipe": "skala", "teks": "Pengalaman MENGAPLIKASI: murid menerapkan pada masalah/tugas kontekstual dan otentik (K)", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q12"}, {"tipe": "skala", "teks": "Pengalaman MEREFLEKSI: murid mengevaluasi proses, hasil, dan strategi belajarnya", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q13"}, {"tipe": "skala", "teks": "Mendorong penalaran kritis dan kreativitas melalui pertanyaan tingkat tinggi dan pemecahan masalah", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q14"}, {"tipe": "skala", "teks": "Murid berpartisipasi aktif, bukan hanya mendengarkan; guru berperan sebagai fasilitator", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q15"}, {"tipe": "skala", "teks": "Pembelajaran menggembirakan: suasana aman, positif; murid termotivasi dan percaya diri", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q16"}, {"tipe": "skala", "teks": "Diferensiasi: dukungan/tantangan sesuai kebutuhan dan kesiapan murid", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q17"}, {"tipe": "bagian", "teks": "III. Kemitraan, Lingkungan, dan Digital", "id": "q18"}, {"tipe": "skala", "teks": "Kolaborasi murid (tim kerja, peran jelas) dan kemitraan dengan DUDI/praktisi/komunitas bila relevan (K)", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q19"}, {"tipe": "skala", "teks": "Lingkungan belajar (fisik, bengkel/lab, virtual) tertata, aman, mendukung; K3LH dan 5R diterapkan (K)", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q20"}, {"tipe": "skala", "teks": "Teknologi dimanfaatkan secara bermakna dan etis (sumber belajar, simulasi, kolaborasi, AI sebagai alat bantu)", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q21"}, {"tipe": "skala", "teks": "Produk/jasa/proyek murid mengarah pada standar kompetensi kerja atau kebutuhan nyata (K)", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q22"}, {"tipe": "bagian", "teks": "IV. Asesmen", "id": "q23"}, {"tipe": "skala", "teks": "Asesmen formatif berlangsung selama pembelajaran (observasi, tanya-jawab, exit ticket, checklist unjuk kerja)", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q24"}, {"tipe": "skala", "teks": "Umpan balik spesifik dan tepat waktu; murid diberi kesempatan memperbaiki", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q25"}, {"tipe": "skala", "teks": "Kriteria/rubrik penilaian diketahui murid dan selaras TP", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q26"}, {"tipe": "bagian", "teks": "V. Pengelolaan Kelas dan Karakter (Profil Lulusan)", "id": "q27"}, {"tipe": "skala", "teks": "Pengelolaan waktu, transisi, dan perilaku murid efektif; tata tertib ditegakkan secara positif", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q28"}, {"tipe": "skala", "teks": "Interaksi guru-murid hangat, adil, inklusif; bahasa komunikatif dan santun", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q29"}, {"tipe": "skala", "teks": "Dimensi profil lulusan yang direncanakan tampak dalam kegiatan (kemandirian, kolaborasi, komunikasi, dll.)", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q30"}, {"tipe": "bagian", "teks": "VI. Kegiatan Penutup", "id": "q31"}, {"tipe": "skala", "teks": "Menyimpulkan bersama dan merefleksikan pembelajaran (apa, mengapa, bagaimana dipakai di dunia kerja)", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q32"}, {"tipe": "skala", "teks": "Memberi tindak lanjut (pengayaan/remedial/tugas) dan informasi pembelajaran berikutnya; merapikan alat/bengkel", "opsi": ["1 — Kurang", "2 — Cukup", "3 — Baik", "4 — Sangat Baik"], "komentar": "Bukti / Catatan", "id": "q33"}, {"tipe": "bagian", "teks": "B.3 Catatan Naratif Supervisor", "id": "q34"}, {"tipe": "teks", "teks": "Kekuatan yang tampak:", "id": "q35"}, {"tipe": "teks", "teks": "Area pengembangan:", "id": "q36"}, {"tipe": "bagian", "teks": "C. Instrumen Tindak Lanjut Supervisi Akademik", "id": "q37"}, {"tipe": "bagian", "teks": "C.1 Refleksi Pasca-Observasi (Dialog Reflektif)", "keterangan": "Isi dengan tanggapan guru.", "id": "q38"}, {"tipe": "teks", "teks": "Menurut Anda, bagian mana yang paling berhasil membuat murid belajar mendalam? Apa buktinya?", "id": "q39"}, {"tipe": "teks", "teks": "Apa yang ingin Anda ubah jika mengulang pembelajaran ini?", "id": "q40"}, {"tipe": "teks", "teks": "Bagaimana hasil asesmen/produk murid dibandingkan TP?", "id": "q41"}, {"tipe": "teks", "teks": "Apa kendala (waktu, sarana, kemitraan, digital) dan dukungan yang dibutuhkan?", "id": "q42"}, {"tipe": "bagian", "teks": "C.2 Rencana Tindak Lanjut dan Pembinaan", "keterangan": "Pilihan bentuk pembinaan: coaching/mentoring sejawat · kunjungan kelas timbal balik · komunitas belajar (KKG/MGMP/Komunitas Praktisi di Platform Merdeka Mengajar) · lokakarya perangkat dan asesmen · magang/industry attachment guru produktif · pelatihan teknologi/AI · pendampingan penyusunan modul ajar.", "id": "q43"}, {"tipe": "teks", "teks": "Rencana tindak lanjut 1 — tulis: temuan/area pengembangan | bentuk pembinaan | target & indikator keberhasilan | penanggung jawab | waktu", "id": "q44"}, {"tipe": "teks", "teks": "Rencana tindak lanjut 2 — tulis: temuan/area pengembangan | bentuk pembinaan | target & indikator keberhasilan | penanggung jawab | waktu", "id": "q45"}, {"tipe": "teks", "teks": "Rencana tindak lanjut 3 — tulis: temuan/area pengembangan | bentuk pembinaan | target & indikator keberhasilan | penanggung jawab | waktu", "id": "q46"}, {"tipe": "teks", "teks": "Rencana tindak lanjut 4 — tulis: temuan/area pengembangan | bentuk pembinaan | target & indikator keberhasilan | penanggung jawab | waktu", "id": "q47"}, {"tipe": "bagian", "teks": "C.3 Pemantauan dan Evaluasi Tindak Lanjut", "id": "q48"}, {"tipe": "teks", "teks": "Pemantauan tindak lanjut — tulis: tanggal monitoring | kegiatan yang dilakukan guru | perkembangan (Tercapai / Sebagian / Belum) | rekomendasi lanjutan", "id": "q49"}, {"tipe": "bagian", "teks": "C.4 Simpulan dan Pengesahan", "id": "q50"}, {"tipe": "pilihan", "teks": "Hasil supervisi", "opsi": ["Sangat Baik", "Baik", "Cukup", "Perlu Pembinaan Intensif"], "id": "q51"}, {"tipe": "teks", "teks": "Komitmen guru:", "id": "q52"}]$j$::jsonb
where not exists (select 1 from public.supervisi_form where judul = 'Instrumen Supervisi Pembelajaran dan Tindak Lanjut SMK (Pembelajaran Mendalam)');

do $$
declare pra_id uuid; sup_id uuid;
begin
  select id into pra_id from public.supervisi_form where judul = 'Instrumen Pra-Supervisi Akademik SMK (Pembelajaran Mendalam)' limit 1;
  select id into sup_id from public.supervisi_form where judul = 'Instrumen Supervisi Pembelajaran dan Tindak Lanjut SMK (Pembelajaran Mendalam)' limit 1;

  -- Supervisi = induk paket, Pra-Supervisi ikut
  update public.supervisi_form set paket_ids = array[pra_id] where id = sup_id;

  -- Jadwal yang belum selesai pindah ke form baru
  update public.supervisi_jadwal set form_id = sup_id
  where status = 'terjadwal'
    and form_id in (select id from public.supervisi_form
                    where judul in ('Instrumen Umpan Balik Perencanaan Pembelajaran Mendalam',
                                    'Instrumen Implementasi dan Refleksi Perencanaan Pembelajaran'));

  -- Tandai form lama
  update public.supervisi_form set judul = '[Lama] ' || judul
  where judul in ('Instrumen Umpan Balik Perencanaan Pembelajaran Mendalam',
                  'Instrumen Implementasi dan Refleksi Perencanaan Pembelajaran');
end $$;
